//! The database schema must stay byte-identical to the one shipped with the
//! Python bot, so that existing `bot_data.db` files keep working.

use sha2::{Digest, Sha384};

const MIGRATION: &[u8] = include_bytes!("../migrations/0001_init.sql");

/// SHA-384 of `migrations/0001_init.sql` as generated by the original project.
const ORIGINAL_SHA384: &str = concat!(
    "01797111e88156ceb6c17a06d2325cf3a993ddcb6cbfccc291bba4a9edb0cc9c",
    "6160d4e40767b3ed8a2cb4ebb379ec69",
);

fn to_hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;

    bytes.iter().fold(String::new(), |mut output, byte| {
        let _ = write!(output, "{byte:02x}");
        output
    })
}

#[test]
fn migration_is_byte_identical_to_the_python_schema() {
    assert_eq!(to_hex(&Sha384::digest(MIGRATION)), ORIGINAL_SHA384);
}
